  const ty = new Map((Array.isArray(model && model.nodes) ? model.nodes : []).filter(n => n && typeof n === 'object' && typeof n.id === 'string').map(n => [n.id, n.type]));
  const pk = id => OWN_BOXES.includes(ty.get(id)); // a profile is a package
