    const c = !cs.length ? '' : `${cmPlural(cs.length, 'connector')}${named(cs).length ? ' (' + named(cs).map(cname).join(', ') + (far(cs) ? `, and ${far(cs)} in other views` : '') + ')' : ''}`;
