      if (!stacks.has(key)) stacks.set(key, { calls: [], up: [] });
      const st = stacks.get(key), call = { x, st, k: st.calls.length, key, chain: new Set(chain(x.parent)), ops: chain(x.parent), answers: [] };
      st.calls.push(call); st.up.push(call.k);
