const UC_LOOK = { boxTypes: ['uml.Subject', 'uml.Package'], qualify: false, shape: x => (x.type === 'uml.Subject' ? 'subject' : 'package'), word: x => (x.type === 'uml.Subject' ? 'Subject' : 'Package') };
