  const ins = new Map(), outs = new Map(), bump = (m, id) => m.set(id, (m.get(id) || 0) + 1);
  I.flows.forEach(e => { bump(outs, e.from); bump(ins, e.to); });
  // what a name counts: the flows the model after draws; a removed node, all it had, the model before's (audit 56)
  const sIn = new Map(), sOut = new Map(); I.flows.forEach(e => { if (liveLine(e, I.gone) || I.gone(e.from)) bump(sOut, e.from); if (liveLine(e, I.gone) || I.gone(e.to)) bump(sIn, e.to); });
  const bar = id => I.el(id).type === 'uml.ForkNode' || I.el(id).type === 'uml.JoinNode';
  const nodes = I.ids.map(id => { const x = I.el(id), shape = ovOwn(OV_SHAPE, x.type) || 'rounded', d = { id, label: [...(['diamond', 'ov-use', 'ov-inline'].includes(shape) ? ovStereo(x).map(t => `«${t}»`) : []), ...(ovLabel(x) ? [ovLabel(x)] : [])].join(' '), type: x.type, kind: 'file', shape, col: at(id)[0], row: at(id)[1] };
    const sd = x.type === 'uml.Interaction' ? ovInline(model, I, x) : null;
    d.aria = ovNodeName(model, I, x, sIn.get(id) || 0, sOut.get(id) || 0, sd); d.saysOpens = x.type === 'uml.InteractionUse' || x.type === 'uml.Interaction' && !sd;
    if (shape === 'rounded') d.stereotypes = ovStereo(x);
    if (shape === 'bar') Object.assign(d, { busy: Math.max(ins.get(id) || 0, outs.get(id) || 0), down });
    if (shape === 'ov-inline') { const b = sd && sd.run && sd.run.bounds, tw = tagSize(`sd ${d.label}`).w + 2 * OV_SD.pad;
      // drawn inline, it reads the lifelines and messages its interaction draws: what diff() marks it by (audit 48)
      // and its fragments and operands, which marks() reads in that view (readsIn, audit 49)
      const rd = b ? [...new Set([...OV_ARR(sd.view.nodeIds), ...sqDrawnMessages(model, sd.view).map(o => o.id), ...OV_ARR(sd.run.nodes).map(n => n && n.id)].filter(x => typeof x === 'string'))] : [];
      return { ...d, ...(b ? { w: Math.ceil(Math.max(b.w + 2 * OV_SD.pad, tw)), h: Math.ceil(ovTagOf(d.label) + b.h), sd: { bounds: b, markup: ovInner(sd.run, sd.view, model) }, ...(rd.length ? { reads: rd, readsIn: sd.view.id } : {}) } : useSize(d.label)) }; }
    return { ...d, ...SHAPE[shape].size(d) }; });
  const edges = I.lines.map(e => ({ id: e.id, _id: e.id, type: e.type, from: e.from, to: e.to, aria: ovFlowName(I, e), ...(OV_OBJ(e.style) || typeof e.style === 'string' ? { style: e.style } : {}),
    ...(e.type === 'uml.CommentLink' ? { end: { from: 'none', to: 'none', dashed: true } }
      : { end: { from: 'none', to: 'open' }, label: flowLabel(e) || undefined, cut: 280, ...(bar(e.from) ? { fromSide: 'right' } : {}), ...(bar(e.to) ? { toSide: 'left' } : {}) }) }));
  // a typed view makes no room for a label (layoutGraph's labelRoom is a map's). A row's nodes share its top, not their middle,
  // so a flow between two of different heights jogs halfway across the gap, and its label sits on one half, clear of the
  // nodes' stubs (22 px): the gap is twice that and the widest label laid out right, its 18 px height laid out down.
  // ponytail: one gap for every column, so one long guard widens them all (to ~612 px at the 280 px cut); room only where a
