    if (tag !== undefined && shape !== undefined) styles.set(tag, { shape, mapped: SZ_SHAPE.get(shape.toLowerCase()) });
    for (const k of keys(s, 'views.configuration.styles.elements')) if (k !== 'tag' && k !== 'shape') looks.add(k);
