      const own = n.type === 'c4.Person' ? 'person' : 'box', { shape, mapped } = style || {};
      if (shape && !mapped) say(r.path, 'approximated', `${n.label}: shape ${shape} is drawn as a box`);
      if (shape && (mapped || 'box') !== own) n.props.shape = mapped || 'box';
