  if (id != null) { const m = BD_ARR(o.members).find(x => BD_OBJ(x) && x.id === id); return m ? bdTypeGuard(model, bdEdit(model, o, m, text)) : null; }
  const r = bdParse(text, o, model); if (r.error) return r;
